VALUES ('han-jing', '虔', ARRAY[]::text[], '姬', '韩', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '前403年与魏、赵同受周室册封为诸侯，韩国正式立国，定都阳翟，开启战国历史，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩景侯"}]'::jsonb, '景侯', NULL, '韩景侯')
