VALUES ('han-r1', '取', ARRAY[]::text[], '姬', '韩', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '景侯之子，烈侯。在位十二年，韩国初立，实力一般，无力争霸，国势平稳，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩烈侯"}]'::jsonb, '烈侯', NULL, '韩烈侯')
