VALUES ('han-r2', '猷', ARRAY[]::text[], '姬', '韩', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '文侯，在位九年。韩国继续发展，未成大患，国势平稳，无力争霸，事迹载于《史记》相关记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩文侯"}]'::jsonb, '文侯', NULL, '韩文侯')
