VALUES ('han-r3', '屯蒙', ARRAY[]::text[], '姬', '韩', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '哀侯，在位仅三年。韩国实力尚弱，无力外争，维持小国局面，国势平平，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩哀侯"}]'::jsonb, '哀侯', NULL, '韩哀侯')
