VALUES ('han-r4', '若山', ARRAY[]::text[], '姬', '韩', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '共侯，曾与赵攻魏，于浊泽大胜。因与赵争利未灭魏，魏得以存续，韩国错失良机，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩共侯"}]'::jsonb, '共侯', NULL, '韩共侯')
