VALUES ('han-r5', '武', ARRAY[]::text[], '姬', '韩', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '即韩昭侯，任申不害变法，以术治国。韩国国力达于最强，诸侯不敢侵伐，为韩国巅峰，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩釐侯"}]'::jsonb, '釐侯', NULL, '韩釐侯')
