VALUES ('han-r6', '康', ARRAY[]::text[], '姬', '韩', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '昭侯之子，宣惠王。在位时韩国称王，参与合纵连横，国势尚可，无力争霸，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩宣惠王"}]'::jsonb, '宣惠王', NULL, '韩宣惠王')
