VALUES ('han-r7', '仓', ARRAY[]::text[], '姬', '韩', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '襄王，在位十五年。与诸侯周旋，韩国已渐弱，无力争霸，国势转衰，事迹载于《史记》相关记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩襄王"}]'::jsonb, '襄王', NULL, '韩襄王')
