VALUES ('han-r8', '咎', ARRAY[]::text[], '姬', '韩', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '在位二十三年，秦国东进，韩国屡遭攻伐，割地求和，国势危急，濒临灭亡，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩釐王"}]'::jsonb, '釐王', NULL, '韩釐王')
