VALUES ('han-r9', '然', ARRAY[]::text[], '姬', '韩', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '桓惠王，在位三十三年。韩国沦为秦国附庸，割地求和，国势危急，濒临灭亡，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩桓惠王"}]'::jsonb, '桓惠王', NULL, '韩桓惠王')
