VALUES ('han-r10', '安', ARRAY[]::text[], '姬', '韩', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '韩国末代君主。前230年秦灭韩，国亡，韩国历史终结，姬姓韩国不复存在，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/安"}]'::jsonb, NULL, NULL, '安')
