VALUES ('han-fei', '韩非', ARRAY[]::text[], NULL, NULL, -280, 1, NULL, 'year', -233, 1, NULL, 'year', ARRAY['思想家'], '法家集大成者，秦王政重其书，后遭李斯害死；代表作有《孤愤》《五蠹》，主张法、术、势并用；入秦后遭李斯构陷，在狱中自尽。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩非"}]'::jsonb, NULL, NULL, NULL)
